import Vue from "vue";
import upload from "./upload.vue";
var UploadConstructor = Vue.extend(upload);
var instance;
var zIndex = 1000;
function appendInstance() {
  var topWindow = window.top;
  var maskList = topWindow.document.querySelectorAll('.ivu-modal-mask');
  var zIndexList = [];
  for (var i = 0; i < maskList.length; i++) {
    zIndexList.push(Number(maskList[i].style.zIndex));
  }
  zIndexList.sort(function (a, b) {
    return a - b;
  });
  if (zIndexList.length) {
    zIndex = zIndexList[zIndexList.length - 1] + 1;
  }
  topWindow.document.body.appendChild(instance.$el);
}
function UploadImg(options) {
  instance = new UploadConstructor({
    data: options
  });
  instance.$mount();
  appendInstance();
  instance.visible = true;
  instance.zIndex = zIndex;
  return instance;
}
export default UploadImg;
